#!/bin/bash
# Lucent pre-commit hook
# Automatically generated by `lucent init --hooks`

set -e

echo "🔍 Running Lucent code quality checks..."

# Get staged files
STAGED_FILES=$(git diff --cached --name-only --diff-filter=ACM | grep -E '\.(rs|py|js|ts|jsx|tsx|go|java|c|cpp|cs)$' || true)

if [ -z "$STAGED_FILES" ]; then
    echo "✅ No source files staged for commit"
    exit 0
fi

# Run Lucent analysis on each staged file
VIOLATIONS_FOUND=0

for file in $STAGED_FILES; do
    if [ -f "$file" ]; then
        echo "  Analyzing $file..."

        # Run analysis with fail-on-error flag
        if ! lucent analyze "$file" --format json > /dev/null 2>&1; then
            echo "  ❌ Quality gates failed for $file"
            VIOLATIONS_FOUND=1
        fi
    fi
done

if [ $VIOLATIONS_FOUND -eq 1 ]; then
    echo ""
    echo "❌ Lucent quality gates failed"
    echo ""
    echo "Some files have code quality violations."
    echo "Run 'lucent analyze <file>' to see details."
    echo ""
    echo "To skip this check, use 'git commit --no-verify'"
    exit 1
fi

echo "✅ All files passed Lucent quality gates"
exit 0
